import heapq

def earliest_earnings(N, M, trains):
    graph = defaultdict(list)
    for x, s, t, l in trains:
        graph[x].append((s + l, t + l))

    def dijkstra(start_time):
        heap = [(start_time, 1)]
        visited = set()

        while heap:
            time, station = heapq.heappop(heap)
            if station == N:
                return time
            if station in visited:
                continue
            visited.add(station)

            for dep_time, arr_time in graph[station]:
                if dep_time >= time:
                    heapq.heappush(heap, (arr_time, station + 1))

        return float('inf')

    left, right = 0, 86400
    while left < right:
        mid = (left + right) // 2
        if dijkstra(mid) - mid < 1800:
            right = mid
        else:
