import sys
from collections import defaultdict
import heapq

def find_earliest_booking():
    N, M = map(int, input().split())
    trains = defaultdict(list)

    for _ in range(M):
        X, S, T, L = map(int, input().split())
        trains[X].append((S, T, L))

    def can_reach_destination(start_time, start_station):
        pq = [(start_time, start_station)]
        visited = set()

        while pq:
            current_time, current_station = heapq.heappop(pq)

            if current_station == N:
                return current_time

            if (current_station, current_time % 86400) in visited:
                continue

            visited.add((current_station, current_time % 86400))

            for next_train in trains[current_station]:
                next_departure, next_arrival, next_delay = next_train
                wait_time = max(0, next_departure - (current_time % 86400))
                new_time = (current_time + wait_time + next_delay) % 86400

                if new_time >= next_arrival:
                    continue

                heapq.heappush(pq, (new_time, current_station + 1))

        return float('inf')

    left, right = 0, 86399
    result = "impossible"

    while left <= right:
        mid = (left + right) // 2
        if can_reach_destination(mid, 1) <= mid + 1800:
            result = str(mid)
            right = mid - 1
        else:
            left = mid + 1

    return result

